previewCss:
.darma-loader-darma-b15-stapler-press { --accent: var(--loader-color, #0f766e); --accent-2: var(--loader-secondary-color, #5eead4); width: var(--loader-size, 126px); height: calc(var(--loader-size, 126px) * .56); position: relative; }
.darma-loader-darma-b15-stapler-press .darma-loader-darma-b15-stapler-press__base { position: absolute; bottom: 10%; left: 4%; width: 92%; height: 18%; border-radius: 4px; background: linear-gradient(#64748b, #1e293b); }
.darma-loader-darma-b15-stapler-press .darma-loader-darma-b15-stapler-press__arm { position: absolute; bottom: 30%; left: 4%; width: 92%; height: 21%; border-radius: 5px 8px 8px 5px; background: linear-gradient(var(--accent-2), var(--accent)); transform-origin: 3% 100%; animation: darma-loader-darma-b15-stapler-press-staple-press calc(var(--loader-speed, 1s) * 1.3) cubic-bezier(.5, 0, .3, 1) infinite; }
.darma-loader-darma-b15-stapler-press i { position: absolute; bottom: 27%; right: 14%; width: 8%; height: 9%; border-top: 3px solid var(--accent-2); border-left: 3px solid var(--accent-2); border-right: 3px solid var(--accent-2); border-radius: 2px 2px 0 0; opacity: 0; animation: darma-loader-darma-b15-stapler-press-staple-pop calc(var(--loader-speed, 1s) * 1.3) ease-out infinite; }
@keyframes darma-loader-darma-b15-stapler-press-staple-press { 0%, 100% { transform: rotate(-13deg); } 45%, 58% { transform: rotate(0deg); } }
@keyframes darma-loader-darma-b15-stapler-press-staple-pop { 0%, 42% { opacity: 0; transform: translateY(-60%); } 52%, 82% { opacity: 1; transform: translateY(0); } 100% { opacity: 0; transform: translateY(0); } }

